  const result = issueInvoice(issued, [issued.number]);

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice returns NOT_DRAFT for sent invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const sentInvoice = { ...invoice, status: 'sent' };

  const result = issueInvoice(sentInvoice, []);

  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const originalStatus = invoice.status;
  const originalNumber = invoice.number;

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.number, originalNumber);
});

test('issueInvoice does not mutate lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const originalQty = invoice.lines[0].qty;

  const issued = issueInvoice(invoice, []).value;

  // Modify the issued invoice's line
  issued.lines[0].qty = 10;

  // Original should not be affected
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('issueInvoice works after adding and removing lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const withAdd = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 }).value;
  const withRemove = removeLine(withAdd, 'DES-HOUR').value;
  const result = issueInvoice(withRemove, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2025-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
});

